package com.ragpipeline.config;import io.qdrant.client.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;@Configuration public class QdrantConfig{@Bean QdrantClient qdrantClient(@Value("${qdrant.host}")String host,@Value("${qdrant.port}")int port){return new QdrantClient(QdrantGrpcClient.newBuilder(host,port,false).build());}}
